async function exportCurrentThumbnail(){const video=$("previewVideo");if(!video||video.readyState<2||!video.videoWidth)return toast("Load a video and wait for the preview first");const canvas=document.createElement("canvas"),scale=Math.min(1,1920/video.videoWidth);canvas.width=Math.max(1,Math.round(video.videoWidth*scale));canvas.height=Math.max(1,Math.round(video.videoHeight*scale));const ctx=canvas.getContext("2d");if(!ctx)return toast("Could not create thumbnail canvas","error");ctx.drawImage(video,0,0,canvas.width,canvas.height);const clip=selected(),title=clip?.title||state.seriesTitle;const style=clip?.titleStyle||state.titleStyle;const size=clamp(Number(style.size)||30,14,108)*scale;ctx.font=`800 ${size}px "${String(style.font||"Inter").replace(/[^\w -]/g,"")}"`;ctx.textAlign="center";ctx.textBaseline="top";ctx.lineJoin="round";ctx.lineWidth=Math.max(2,size*.12);ctx.strokeStyle=style.outline||"#000000";ctx.fillStyle=style.color||"#ffffff";const words=title.split(/\s+/);const lines=[];let line="";for(const word of words){const next=line?line+" "+word:word;if(ctx.measureText(next).width>canvas.width*.88&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);lines.slice(0,3).forEach((value,i)=>{const y=canvas.height*.09+i*(size*1.16);ctx.strokeText(value,canvas.width/2,y,canvas.width*.9);ctx.fillText(value,canvas.width/2,y,canvas.width*.9)});canvas.toBlob(blob=>{if(!blob)return toast("Thumbnail export failed","error");downloadBlob(blob,`${(state.projectName||"clipsmith").replace(/[^\w-]+/g,"-")}-thumbnail.png`);toast("Thumbnail PNG saved")},"image/png")}
