async function renderClip(c,i,mode){const fx={...DEFAULT_FX,...(c.fx||{})},needsFilter=fx.speed!==1||fx.brightness!==0||fx.contrast!==1||fx.saturation!==1||fx.blur>0||fx.volume!==1||fx.mute||fx.normalize;if(mode==='copy'&&needsFilter)throw Error('Original stream cannot render visual/audio edits. Choose Smart or High quality.');const ff=await getFFmpeg(),input=`source-${uid()}`,output=`clip-${uid()}.mp4`;await ff.writeFile(input,await ff.__fetchFile(state.sourceFile));const duration=Math.max(.5,c.end-c.start);const buildArgs=copy=>{const args=['-ss',String(c.start),'-i',input,'-t',String(duration),'-map','0:v:0?','-map','0:a:0?'];if(copy)args.push('-c','copy','-avoid_negative_ts','make_zero');else{const vf=[];if(fx.brightness||fx.contrast!==1||fx.saturation!==1)vf.push(`eq=brightness=${fx.brightness}:contrast=${fx.contrast}:saturation=${fx.saturation}`);if(fx.blur>0)vf.push(`boxblur=${fx.blur}:1`);if(fx.speed!==1)vf.push(`setpts=${1/fx.speed}*PTS`);if(mode==='mobile')vf.push("scale='min(1280,iw)':-2");if(vf.length)args.push('-vf',vf.join(','));if(fx.mute)args.push('-an');else{const af=[];if(fx.speed!==1)af.push(`atempo=${clamp(fx.speed,.5,2)}`);if(fx.volume!==1)af.push(`volume=${fx.volume}`);if(fx.normalize)af.push('loudnorm=I=-16:TP=-1.5:LRA=11');if(af.length)args.push('-af',af.join(','))}args.push('-c:v','libx264','-preset','veryfast','-crf',mode==='mobile'?'29':mode==='high'?'20':'23','-c:a','aac','-b:a',mode==='mobile'?'96k':'128k','-movflags','+faststart')}args.push(output);return args};const execute=async(copy)=>{const onProgress=({progress})=>qstatus(c.id,copy?'copying':'rendering',Math.round(progress*100));ff.on('progress',onProgress);try{await ff.exec(buildArgs(copy));const data=await ff.readFile(output);return new Blob([data],{type:'video/mp4'})}finally{if(ff.off)ff.off('progress',onProgress)}};try{try{return await execute(mode==='copy'||(mode==='smart'&&!needsFilter))}catch(error){if(mode==='smart'&&!needsFilter){qstatus(c.id,'Smart retry: re-encoding',0);try{await ff.deleteFile(output)}catch{}return await execute(false)}throw error}}finally{try{await ff.deleteFile(input)}catch{}try{await ff.deleteFile(output)}catch{}}}
async function startExport(){if(exportBusy)return;exportBusy=true;$("startExportBtn").disabled=true;$("exportRecoveryActions").classList.add('hidden');const clips=[...state.clips];try{for(let i=0;i<clips.length;i++){const c=clips[i];qstatus(c.id,'starting',0);try{const blob=await renderClip(c,i,exportMode);downloadBlob(blob,outputName(c,i));qstatus(c.id,'done',100);await new Promise(r=>setTimeout(r,50))}catch(e){qstatus(c.id,'failed',0);$("exportRecoveryActions").classList.remove('hidden');$("recoveryText").textContent=e.message||'The browser could not render this clip.';toast('Export stopped — recovery options are ready','error');break}}}finally{exportBusy=false;$("startExportBtn").disabled=false}}
$("startExportBtn").onclick=startExport;$("recoveryOriginalBtn").onclick=()=>{exportMode='copy';startExport()};$("recoveryLowBtn").onclick=()=>{exportMode='mobile';startExport()};$("recoverySingleClipBtn").onclick=async()=>{const c=selected();if(!c)return toast('Select one clip first');try{const b=await renderClip(c,0,'mobile');downloadBlob(b,outputName(c,0));toast('Selected clip exported')}catch(e){toast(e.message||'Single-clip export failed','error')}};
$("saveProjectBtn").onclick=()=>{const m=createProjectManifest({projectName:state.projectName,sourceFileName:state.sourceFile?.name||state.sourceMeta?.fileName||'',sourceFileSize:state.sourceFile?.size||state.sourceMeta?.fileSize||0,sourceDuration:state.duration,sourceUrl:state.sourceMeta?.sourceUrl||'',clips:state.clips,controls:{aspectSelect:state.aspect,skipRanges:state.skipRanges,subtitleCues:state.subtitleCues,subtitleSettings:state.subtitleSettings,exportAspect:state.exportAspect}},new Date().toISOString());downloadBlob(new Blob([JSON.stringify(m,null,2)],{type:'application/json'}),`${state.projectName.replace(/\W+/g,'-')||'clipsmith-project'}.clipsmith.json`);toast('Project saved')};$("loadProjectBtn").onclick=()=>$("projectFileInput").click();$("projectFileInput").onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const m=validateProjectManifest(JSON.parse(await f.text()));if(!m)throw Error('Invalid ClipSmith project file');state.projectName=m.projectName;state.clips=m.clips;state.aspect=m.controls?.aspectSelect||'16:9';state.skipRanges=Array.isArray(m.controls?.skipRanges)?m.controls.skipRanges.filter(r=>Number.isFinite(Number(r?.start))&&Number.isFinite(Number(r?.end))&&Number(r.end)>Number(r.start)).slice(0,500).map(r=>({id:typeof r.id==='string'?r.id:uid(),start:Math.max(0,Number(r.start)),end:Math.max(0,Number(r.end)),label:'Promo / ad break'})):[];state.subtitleCues=Array.isArray(m.controls?.subtitleCues)?m.controls.subtitleCues.filter(q=>Number.isFinite(Number(q.start))&&Number.isFinite(Number(q.end))&&Number(q.end)>Number(q.start)&&String(q.text||'').trim()).slice(0,50000):[];state.subtitleSettings={style:"Classic",highlight:"#9e83ff",positionY:82,...(m.controls?.subtitleSettings||{})};state.exportAspect=m.controls?.exportAspect||"source";state.duration=m.source.duration||0;state.sourceMeta={fileName:m.source.fileName,fileSize:m.source.fileSize,sourceUrl:m.source.url||'',duration:state.duration};state.sourceFile=null;state.selectedId=state.clips[0]?.id||null;$("projectName").value=state.projectName;$("mediaName").textContent=`Saved project · ${state.sourceMeta.fileName||'video'}`;$("previewEmptyTitle").textContent='Project opened';$("previewEmptyHint").textContent='Re-import the source video to preview and export.';$("previewEmpty").classList.remove('hidden');commit();renderAll();toast('Project opened')}catch(err){toast(err.message||'Could not open project','error')}finally{e.target.value=''}};
$("projectName").oninput=e=>{state.projectName=e.target.value;persist()};
$("generateIdeasBtn").onclick=()=>{const ideas=generateCreatorIdeas({title:selected()?.title||state.seriesTitle,fileName:state.sourceFile?.name||'',transcript:$("ideasTranscript").value,visualTags:state.visualTags,platform:$("creatorPlatform").value,tone:$("creatorTone").value,language:$("creatorLanguage").value});$("creatorResults").innerHTML=`<div class="result-card"><span>Caption ideas</span>${ideas.captions.map(x=>`<div class="copy-line"><p>${esc(x)}</p><button data-copy="${esc(x)}">Copy</button></div>`).join('')}</div><div class="result-card"><span>Hashtags</span><div class="copy-line"><p>${esc(ideas.hashtags.join(' '))}</p><button data-copy="${esc(ideas.hashtags.join(' '))}">Copy</button></div></div><div class="result-card"><span>Hooks</span>${(ideas.hooks||ideas.captions||[]).slice(0,5).map(x=>`<div class="copy-line"><p>${esc(x)}</p><button data-copy="${esc(x)}">Copy</button></div>`).join("")}</div><div class="result-card"><span>Short titles</span>${(ideas.titles||[]).map(x=>`<div class="copy-line"><p>${esc(x)}</p><button data-copy="${esc(x)}">Copy</button></div>`).join("")}</div>`};$("creatorResults").onclick=e=>{const b=e.target.closest('[data-copy]');if(b)navigator.clipboard?.writeText(b.dataset.copy).then(()=>toast('Copied'))};
async function analyzeCurrentFrame(){const v=$("previewVideo"),status=$("visualAnalysisStatus"),btn=$("analyzeFrameBtn");if(!state.sourceFile||v.readyState<2)return toast('Load a video first');btn.disabled=true;status.textContent='Loading local object detection…';try{if(!visionModelPromise){visionModelPromise=(async()=>{await import('https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js');const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@tensorflow-models/coco-ssd@2.2.3/dist/coco-ssd.min.js';document.head.appendChild(s);await new Promise((res,rej)=>{s.onload=res;s.onerror=rej});return window.cocoSsd.load({base:'lite_mobilenet_v2'})})()}const model=await visionModelPromise;const p=await model.detect(v,10,.35);state.visualTags=[...new Set(p.map(x=>x.class))].slice(0,8);status.textContent=state.visualTags.length?`Detected: ${state.visualTags.join(', ')}`:'No clear objects detected';commit();toast('Frame analyzed')}catch(e){visionModelPromise=null;status.textContent='Local analysis unavailable; add a transcript or description instead.';toast('Frame analysis unavailable','error')}finally{btn.disabled=false}}
$("analyzeFrameBtn")?.addEventListener('click',analyzeCurrentFrame);
$("normalizeAudioBtn")?.addEventListener('click',()=>{const c=selected();if(!c)return toast('Select a clip first');c.fx={...DEFAULT_FX,...c.fx,normalize:true};commit();syncInspector();toast('Audio normalization enabled')});$("normalizeAudioFxBtn")?.addEventListener('click',()=>$("normalizeAudioBtn").click());
$("titleOverlay").addEventListener('pointerdown',dragOverlay);$("captionOverlay").addEventListener('pointerdown',dragOverlay);function dragOverlay(e){const el=e.currentTarget,stage=$("preview-stage"),r=stage.getBoundingClientRect(),start=e.clientY,top0=(parseFloat(getComputedStyle(el).top)||r.height*.17);el.setPointerCapture(e.pointerId);const move=ev=>{el.style.top=`${clamp((top0+ev.clientY-start)/r.height*100,4,90)}%`;el.style.bottom='auto'};const up=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up)};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up)}
